app.MapPost("/payments", async (PaymentRequest req, HttpContext ctx, AppDb db) => {
    var key = ctx.Request.Headers["Idempotency-Key"].ToString();
    if (string.IsNullOrWhiteSpace(key))
        return Results.BadRequest("Idempotency-Key header is required.");

    var existing = await db.PaymentIdempotency
        .FirstOrDefaultAsync(x => x.IdempotencyKey == key);

    if (existing is not null) {
        if (existing.Status == "processing")
            return Results.Conflict("Payment is already being processed.");
        return Results.Content(existing.ResponseBody!, "application/json");
    }

    var record = new PaymentIdempotency {
        IdempotencyKey = key,
        Status = "processing",
        RequestBody = JsonSerializer.Serialize(req),
        ExpiresAt = DateTime.UtcNow.AddHours(24)
    };
    db.PaymentIdempotency.Add(record);
    await db.SaveChangesAsync();

    try {
        var result = await ProcessPaymentAsync(req);
        record.Status = "succeeded";
        record.PaymentId = result.Id;
        record.ResponseBody = JsonSerializer.Serialize(result);
        await db.SaveChangesAsync();
        return Results.Created($"/payments/{result.Id}", result);
    }
    catch (Exception ex) {
        record.Status = "failed";
        record.ResponseBody = JsonSerializer.Serialize(new { error = ex.Message });
        await db.SaveChangesAsync();
        throw;
    }
})
.WithName("CreatePayment");
